// wf-review-action — POST /webhook/review-action. Lets the in-app Governor
// Review tab ACT on a staged freshness proposal: 'dismiss' clears it from the
// feed, 'keep' flags it as worth acting on (DR-0061: a surface is a CONTROL for
// real state, not just a view). Token-gated (fail-closed); the id is validated
// to the fr- shape (no path traversal); it writes only the status of an EXISTING
// proposal and never applies anything to the system itself — bright lines
// (money, credentials, the family's voice) stay manual.

const fs = require('fs');
const path = require('path');

const FRESH_DIR = '/data/finance-events/_freshness';
const TOKEN_FILE = path.join(FRESH_DIR, '.review-token');
const ALLOWED = { dismiss: 'dismissed', keep: 'kept' };

const item = $input.first() || {};
const input = item.json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const headers = input.headers || item.headers || {};

// AUTH (fail-closed): X-Review-Token header or body.token must match the file.
let expectedToken = null;
try { expectedToken = fs.readFileSync(TOKEN_FILE, 'utf8').trim(); } catch (_) {}
const got = (headers['x-review-token'] || headers['X-Review-Token'] || body.token || '').toString();
if (!expectedToken || got !== expectedToken) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}

// Validate the action.
const action = (body.action || '').toString().toLowerCase();
const newStatus = ALLOWED[action];
if (!newStatus) {
  return [{ json: { ok: false, error: 'invalid action (expected dismiss or keep)' } }];
}

// Validate the id to the fr- shape ONLY — no dots, slashes, or path traversal.
const id = (body.id || '').toString();
if (!/^fr-[0-9A-Za-z-]+$/.test(id)) {
  return [{ json: { ok: false, error: 'invalid id' } }];
}
const file = path.join(FRESH_DIR, id + '.json');
if (path.dirname(file) !== FRESH_DIR) {
  return [{ json: { ok: false, error: 'invalid id (path)' } }];
}

// Load, update only the status, write back.
let record;
try { record = JSON.parse(fs.readFileSync(file, 'utf8')); }
catch (_) { return [{ json: { ok: false, error: 'not found' } }]; }
record.status = newStatus;
record.reviewed_at = new Date().toISOString();
try { fs.writeFileSync(file, JSON.stringify(record, null, 2)); }
catch (e) { return [{ json: { ok: false, error: 'write failed: ' + String((e && e.message) || e) } }]; }

return [{ json: { ok: true, id: id, status: newStatus } }];
